def get_36kr_trending(type=None, **_extra):
    import json, os, datetime, time, hashlib, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0382000" if __import__("os").path.isdir("./environment_mix/0382000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    tool_name = "get-36kr-trending"

    def _utcnow():
        return datetime.datetime.utcnow().replace(microsecond=0)

    def _iso(dt):
        if isinstance(dt, str):
            return dt
        return dt.replace(microsecond=0).isoformat() + "Z"

    def _parse_dt(ts):
        if isinstance(ts, datetime.datetime):
            return ts
        if not isinstance(ts, str):
            return None
        s = ts.strip()
        if s.endswith("Z"):
            s = s[:-1]
        try:
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _lat_ms():
        return max(0, min(300000, int((time.time() - t0) * 1000)))

    def _freeze(v):
        if v is None or isinstance(v, (str, int, float, bool)):
            return v
        if isinstance(v, list):
            return [_freeze(x) for x in v]
        if isinstance(v, dict):
            return {k: _freeze(v[k]) for k in sorted(v.keys())}
        return str(v)

    def _norm_params(p):
        if p is None:
            p = {}
        if not isinstance(p, dict):
            return None
        return json.dumps(_freeze(p), ensure_ascii=False, sort_keys=True, separators=(",", ":"))

    def _cache_key(tool, params):
        norm = _norm_params(params)
        s = f"{tool}:{norm}"
        return f"{tool}:" + hashlib.sha256(s.encode("utf-8")).hexdigest()

    def _append_request(api_requests, source_id, request_params, cache_key, snapshot_id, response_status, served_from_cache):
        now = _utcnow()
        api_requests.append({
            "id": "th_req_" + uuid.uuid4().hex,
            "api_key_id": None,
            "tool_name": tool_name,
            "source_id": source_id,
            "request_params": request_params if isinstance(request_params, dict) else {},
            "cache_key": cache_key,
            "snapshot_id": snapshot_id,
            "response_status": int(response_status),
            "latency_ms": int(_lat_ms()),
            "served_from_cache": bool(served_from_cache),
            "created_at": _iso(now),
            "updated_at": _iso(now),
        })

    # Defaults and validation
    if type is None:
        type = "hot"
    if not isinstance(type, str):
        return _err("VALIDATION_ERROR", "type must be a string", field="type")
    allowed = {"hot", "video", "comment", "collect"}
    if type not in allowed:
        return _err("VALIDATION_ERROR", "type not in allowed values", field="type", allowed=sorted(allowed))

    req_params = {"type": type}

    # Load data
    sources = _load("sources.json")
    fetch_jobs = _load("fetch_jobs.json")
    snapshots = _load("trend_snapshots.json")
    snapshot_items = _load("snapshot_items.json")
    trend_items = _load("trend_items.json")
    api_requests = _load("api_requests.json")

    if not isinstance(sources, list):
        sources = sources.get("rows", []) if isinstance(sources, dict) else []
    if not isinstance(fetch_jobs, list):
        fetch_jobs = fetch_jobs.get("rows", []) if isinstance(fetch_jobs, dict) else []
    if not isinstance(snapshots, list):
        snapshots = snapshots.get("rows", []) if isinstance(snapshots, dict) else []
    if not isinstance(snapshot_items, list):
        snapshot_items = snapshot_items.get("rows", []) if isinstance(snapshot_items, dict) else []
    if not isinstance(trend_items, list):
        trend_items = trend_items.get("rows", []) if isinstance(trend_items, dict) else []
    if not isinstance(api_requests, list):
        api_requests = api_requests.get("rows", []) if isinstance(api_requests, dict) else []

    # Resolve source by tool_name -> slug mapping (slug is expected to exist)
    src = None
    for s in sources:
        if isinstance(s, dict) and s.get("slug") == "36kr":
            src = s
            break
    if not src:
        _append_request(api_requests, None, req_params, None, None, 404, False)
        _save("api_requests.json", api_requests)
        return _err("NOT_FOUND", "No configured source available for this tool", tool_name=tool_name)

    if src.get("status") != "active":
        _append_request(api_requests, src.get("id"), req_params, None, None, 404, False)
        _save("api_requests.json", api_requests)
        return _err("NOT_FOUND", "Source is not active", source_id=src.get("id"), status=src.get("status"))

    # Validate against supports_params (reject unknown fields, enum/range)
    sp = src.get("supports_params")
    if not isinstance(sp, dict):
        _append_request(api_requests, src.get("id"), req_params, None, None, 500, False)
        _save("api_requests.json", api_requests)
        return _err("CONFLICT", "source.supports_params invalid", source_id=src.get("id"))
    for k in req_params.keys():
        if k not in sp:
            _append_request(api_requests, src.get("id"), req_params, None, None, 400, False)
            _save("api_requests.json", api_requests)
            return _err("VALIDATION_ERROR", f"unsupported param: {k}", source_id=src.get("id"), field=k)
    # Per-field validation
    for k, rule in sp.items():
        if k not in req_params:
            continue
        v = req_params[k]
        if isinstance(rule, dict):
            rtype = rule.get("type")
            if rtype == "enum":
                vals = rule.get("values")
                if isinstance(vals, list) and v not in vals:
                    _append_request(api_requests, src.get("id"), req_params, None, None, 400, False)
                    _save("api_requests.json", api_requests)
                    return _err("VALIDATION_ERROR", f"{k} not in allowed values", field=k, allowed=vals, source_id=src.get("id"))
            elif rtype == "range":
                mn = rule.get("min")
                mx = rule.get("max")
                if not isinstance(v, (int, float)) or (mn is not None and v < mn) or (mx is not None and v > mx):
                    _append_request(api_requests, src.get("id"), req_params, None, None, 400, False)
                    _save("api_requests.json", api_requests)
                    return _err("VALIDATION_ERROR", f"{k} out of range", field=k, min=mn, max=mx, source_id=src.get("id"))

    ck = _cache_key(tool_name, req_params)
    now = _utcnow()

    # Enforce simple rate limiting/quota based on api_requests (best-effort defaults)
    # rate: 120/min per tool; quota: 5000/day per tool
    window_start = now - datetime.timedelta(seconds=60)
    day_start = now - datetime.timedelta(days=1)
    per_min = 0
    per_day = 0
    for r in api_requests:
        if not isinstance(r, dict):
            continue
        if r.get("tool_name") != tool_name:
            continue
        ct = _parse_dt(r.get("created_at"))
        if not ct:
            continue
        if ct >= window_start:
            per_min += 1
        if ct >= day_start:
            per_day += 1
    if per_min >= 120:
        _append_request(api_requests, src.get("id"), req_params, ck, None, 429, False)
        _save("api_requests.json", api_requests)
        return _err("RATE_LIMIT", "Rate limit exceeded")
    if per_day >= 5000:
        _append_request(api_requests, src.get("id"), req_params, ck, None, 429, False)
        _save("api_requests.json", api_requests)
        return _err("QUOTA_EXCEEDED", "Quota exceeded")

    # Cache hit: ready + not expired
    ready = []
    for sn in snapshots:
        if not isinstance(sn, dict):
            continue
        if sn.get("tool_name") != tool_name:
            continue
        if sn.get("cache_key") != ck:
            continue
        if sn.get("status") != "ready":
            continue
        exp = _parse_dt(sn.get("expires_at"))
        if exp and exp > now:
            ready.append(sn)
    if ready:
        ready.sort(key=lambda x: (_parse_dt(x.get("generated_at")) or datetime.datetime.min), reverse=True)
        sn = ready[0]
        sid = sn.get("id")
        sitems = [si for si in snapshot_items if isinstance(si, dict) and si.get("snapshot_id") == sid]
        sitems.sort(key=lambda x: x.get("rank", 10**9))
        item_map = {it.get("id"): it for it in trend_items if isinstance(it, dict)}
        out = []
        for si in sitems:
            it = item_map.get(si.get("item_id"))
            if not it:
                continue
            out.append({
                "rank": si.get("rank"),
                "score": si.get("score"),
                "metrics": si.get("metrics") if isinstance(si.get("metrics"), dict) else {},
                "extra": si.get("extra") if isinstance(si.get("extra"), dict) else {},
                "item": it,
            })
        _append_request(api_requests, src.get("id"), req_params, ck, sid, 200, True)
        _save("api_requests.json", api_requests)
        return {
            "tool_name": tool_name,
            "source": {"id": src.get("id"), "slug": src.get("slug"), "display_name": src.get("display_name")},
            "cache_key": ck,
            "snapshot": sn,
            "items": out,
            "served_from_cache": True,
        }

    # If in-flight job exists, try fallback to latest stale snapshot
    inflight = None
    for j in fetch_jobs:
        if not isinstance(j, dict):
            continue
        if j.get("cache_key") == ck and j.get("status") in ("queued", "running"):
            inflight = j
            break

    stale = []
    for sn in snapshots:
        if not isinstance(sn, dict):
            continue
        if sn.get("tool_name") != tool_name or sn.get("cache_key") != ck:
            continue
        if sn.get("status") in ("stale", "ready"):
            stale.append(sn)
    if stale:
        stale.sort(key=lambda x: (_parse_dt(x.get("generated_at")) or datetime.datetime.min), reverse=True)
        sn = stale[0]
        sid = sn.get("id")
        sitems = [si for si in snapshot_items if isinstance(si, dict) and si.get("snapshot_id") == sid]
        sitems.sort(key=lambda x: x.get("rank", 10**9))
        item_map = {it.get("id"): it for it in trend_items if isinstance(it, dict)}
        out = []
        for si in sitems:
            it = item_map.get(si.get("item_id"))
            if not it:
                continue
            out.append({
                "rank": si.get("rank"),
                "score": si.get("score"),
                "metrics": si.get("metrics") if isinstance(si.get("metrics"), dict) else {},
                "extra": si.get("extra") if isinstance(si.get("extra"), dict) else {},
                "item": it,
            })
        _append_request(api_requests, src.get("id"), req_params, ck, sid, 200, True)
        _save("api_requests.json", api_requests)
        return {
            "tool_name": tool_name,
            "source": {"id": src.get("id"), "slug": src.get("slug"), "display_name": src.get("display_name")},
            "cache_key": ck,
            "snapshot": sn,
            "items": out,
            "served_from_cache": True,
            "in_flight_job_id": inflight.get("id") if inflight else None,
        }

    _append_request(api_requests, src.get("id"), req_params, ck, None, 404, False)
    _save("api_requests.json", api_requests)
    return _err("NOT_FOUND", "No available snapshot for this request", cache_key=ck, source_id=src.get("id"))

