    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0)
    now_iso = now.isoformat() + "Z"

    TOOL = "get-sspai-rank"
    allowed_tags = ["热门文章", "应用推荐", "生活方式", "效率技巧", "少数派播客"]

    if not isinstance(tag, str) or tag not in allowed_tags:
        return _err("VALIDATION_ERROR", "Invalid tag", allowed=allowed_tags)
    if isinstance(limit, bool) or not isinstance(limit, int):
        return _err("VALIDATION_ERROR", "limit must be an integer")
    if limit < 1 or limit > 100:
        return _err("VALIDATION_ERROR", "limit out of range", min=1, max=100)

    sources = _load("sources.json")
    fetch_jobs = _load("fetch_jobs.json")
    snapshots = _load("trend_snapshots.json")
    items = _load("trend_items.json")
    snapshot_items = _load("snapshot_items.json")
    api_requests = _load("api_requests.json")

    api_key_id = None

    slug = "sspai"
    src = next((s for s in sources if isinstance(s, dict) and s.get("slug") == slug), None)
    if not src:
        latency_ms = int((time.time() - t0) * 1000)
        req_id = "req_" + uuid.uuid4().hex
        api_requests.append({
            "id": req_id,
            "api_key_id": api_key_id,
            "tool_name": TOOL,
            "source_id": None,
            "request_params": {"tag": tag, "limit": limit},
            "cache_key": None,
            "snapshot_id": None,
            "response_status": 401,
            "latency_ms": latency_ms,
            "served_from_cache": False,
            "created_at": now_iso,
            "updated_at": now_iso
        })
        _save("api_requests.json", api_requests)
        return _err("UNAUTHORIZED", "No configured source available for this tool")

    if src.get("status") != "active":
        latency_ms = int((time.time() - t0) * 1000)
        req_id = "req_" + uuid.uuid4().hex
        api_requests.append({
            "id": req_id,
            "api_key_id": api_key_id,
            "tool_name": TOOL,
            "source_id": src.get("id"),
            "request_params": {"tag": tag, "limit": limit},
            "cache_key": None,
            "snapshot_id": None,
            "response_status": 502,
            "latency_ms": latency_ms,
            "served_from_cache": False,
            "created_at": now_iso,
            "updated_at": now_iso
        })
        _save("api_requests.json", api_requests)
        return _err("UPSTREAM_ERROR", "Source is not active")

    supports = src.get("supports_params")
    if not isinstance(supports, dict):
        return _err("VALIDATION_ERROR", "Source supports_params is invalid")

    # Validate declared params exist
    for k in ("tag", "limit"):
        if k not in supports:
            return _err("VALIDATION_ERROR", f"Parameter '{k}' is not supported by this source")

    tag_rule = supports.get("tag")
    if isinstance(tag_rule, dict) and tag_rule.get("type") == "enum":
        vals = tag_rule.get("values")
        if isinstance(vals, list) and tag not in vals:
            return _err("VALIDATION_ERROR", "Invalid tag", allowed=vals)

    limit_rule = supports.get("limit")
    if isinstance(limit_rule, dict):
        if limit_rule.get("type") == "range":
            mn, mx = limit_rule.get("min"), limit_rule.get("max")
            if isinstance(mn, int) and limit < mn: return _err("VALIDATION_ERROR", "limit below min", min=mn)
            if isinstance(mx, int) and limit > mx: return _err("VALIDATION_ERROR", "limit above max", max=mx)

    req_params = {"tag": tag, "limit": limit}
    norm = json.dumps(req_params, ensure_ascii=False, sort_keys=True, separators=(",", ":"))
    cache_key = hashlib.sha256((TOOL + "|" + norm).encode("utf-8")).hexdigest()

    def _parse_dt(s):
        if not isinstance(s, str): return None
        try:
            if s.endswith("Z"): s = s[:-1]
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    ready = []
    for sn in snapshots:
        if not isinstance(sn, dict): 
