def get_theverge_news(**_extra):
    import json, os, datetime, time, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0382000" if __import__("os").path.isdir("./environment_mix/0382000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0)
    now_iso = now.isoformat() + "Z"

    TOOL = "get-theverge-news"
    SOURCE_SLUG = "theverge"

    def _dt_parse(s):
        if s is None:
            return None
        if not isinstance(s, str) or not s:
            return None
        try:
            if s.endswith("Z"):
                s2 = s[:-1]
            else:
                s2 = s
            return datetime.datetime.fromisoformat(s2)
        except Exception:
            return None

    def _new_id(prefix):
        return f"{prefix}_{datetime.datetime.utcnow().strftime('%Y%m%d%H%M%S')}_{hashlib.sha256(os.urandom(16)).hexdigest()[:16]}"

    def _normalize_params(p):
        # no params for this tool
        return {}

    def _cache_key(tool_name, params):
        canonical = json.dumps(params, ensure_ascii=False, sort_keys=True, separators=(",", ":"))
        return f"{tool_name}:{hashlib.sha256(canonical.encode('utf-8')).hexdigest()}"

    def _record_api_request(api_requests, api_key_id, source_id, request_params, cache_key, snapshot_id, status_code, latency_ms, served_from_cache):
        req = {
            "id": _new_id("req"),
            "api_key_id": api_key_id,
            "tool_name": TOOL,
            "source_id": source_id,
            "request_params": request_params,
            "cache_key": cache_key,
            "snapshot_id": snapshot_id,
            "response_status": int(status_code),
            "latency_ms": int(max(0, min(300000, latency_ms))),
            "served_from_cache": bool(served_from_cache),
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        api_requests.append(req)
        _save("api_requests.json", api_requests)
        return req["id"]

    def _tool_to_source(sources):
        for s in sources:
            if s.get("slug") == SOURCE_SLUG:
                return s
        return None

    def _validate_no_params():
        # The vendor schema shows empty properties and additionalProperties false.
        # If caller passed unknown args via _extra, ignore; tool surface has no params.
        return {}

    def _check_supports_params(source_row, params):
        sp = source_row.get("supports_params")
        if not isinstance(sp, dict):
            return _err("VALIDATION_ERROR", "Source supports_params is invalid.")
        # tool has no params; reject if source declares required-only? none in schema. Just ensure no extra fields present.
        if params:
            # if any provided somehow, must be declared
            for k in params.keys():
                if k not in sp:
                    return _err("VALIDATION_ERROR", f"Unknown parameter: {k}")
        return None

    def _enforce_rate_limit(api_requests, tool_name, api_key_id):
        # Simple in-store rate/quotas: global per tool.
        # - RATE_LIMIT: > 60 requests/minute (rolling) for this tool across all callers
        # - QUOTA_EXCEEDED: > 10000 requests/day for this tool across all callers
        window_s = 60
        daily_limit = 10000
        per_min_limit = 60

        now_dt = now
        minute_ago = now_dt - datetime.timedelta(seconds=window_s)
        day_ago = now_dt - datetime.timedelta(hours=24)

        per_min = 0
        per_day = 0
        for r in api_requests:
            if r.get("tool_name") != tool_name:
                continue
            # If api_key_id is present in requests and caller had one we'd filter; there is none, so global.
            ts = _dt_parse(r.get("created_at"))
            if not ts:
                continue
            if ts >= day_ago:
                per_day += 1
            if ts >= minute_ago:
                per_min += 1

        if per_min >= per_min_limit:
            return _err("RATE_LIMIT", "Too many requests.")
        if per_day >= daily_limit:
            return _err("QUOTA_EXCEEDED", "Daily quota exceeded.")
        return None

    def _select_ready_snapshot(trend_snapshots, cache_key):
        best = None
        for s in trend_snapshots:
            if s.get("cache_key") != cache_key:
                continue
            if s.get("status") != "ready":
                continue
            exp = _dt_parse(s.get("expires_at"))
            if not exp or exp <= now:
                continue
            # choose newest generated_at
            gen = _dt_parse(s.get("generated_at")) or datetime.datetime.min
            if best is None:
                best = s
            else:
                best_gen = _dt_parse(best.get("generated_at")) or datetime.datetime.min
                if gen > best_gen:
                    best = s
        return best

    def _select_stale_snapshot(trend_snapshots, cache_key):
        best = None
        for s in trend_snapshots:
            if s.get("cache_key") != cache_key:
                continue
            if s.get("status") not in ("ready", "stale"):
                continue
            gen = _dt_parse(s.get("generated_at")) or datetime.datetime.min
            if best is None:
                best = s
            else:
                best_gen = _dt_parse(best.get("generated_at")) or datetime.datetime.min
                if gen > best_gen:
                    best = s
        return best

    def _assemble_items(snapshot_id, snapshot_items, trend_items):
        # join and sort by rank
        rel = [si for si in snapshot_items if si.get("snapshot_id") == snapshot_id]
        rel.sort(key=lambda x: x.get("rank", 10**9))
        ti_by_id = {t.get("id"): t for t in trend_items}
        out = []
        for si in rel:
            t = ti_by_id.get(si.get("item_id"))
            if not t:
                continue
            if t.get("status") != "active":
                continue
            out.append({
                "id": t.get("id"),
                "source_id": t.get("source_id"),
                "title": t.get("title"),
                "summary": t.get("summary"),
                "url": t.get("url"),
                "author": t.get("author"),
                "language": t.get("language"),
                "published_at": t.get("published_at"),
                "content_type": t.get("content_type"),
                "rank": si.get("rank"),
                "score": si.get("score"),
                "metrics": si.get("metrics"),
                "extra": si.get("extra"),
                "raw_payload": t.get("raw_payload"),
            })
        return out

    # Load datastore
    sources = _load("sources.json")
    fetch_jobs = _load("fetch_jobs.json")
    trend_snapshots = _load("trend_snapshots.json")
    trend_items = _load("trend_items.json")
    snapshot_items = _load("snapshot_items.json")
    api_requests = _load("api_requests.json")

    # Resolve source + validate mapping
    source = _tool_to_source(sources)
    if not source:
        # log request
        latency = int((time.time() - t0) * 1000)
        _record_api_request(api_requests, None, None, {}, None, None, 404, latency, False)
        return _err("NOT_FOUND", f"Source for tool '{TOOL}' not found.")

    if source.get("status") != "active":
        latency = int((time.time() - t0) * 1000)
        _record_api_request(api_requests, None, source.get("id"), {}, None, None, 401, latency, False)
        return _err("UNAUTHORIZED", "No active source available for this tool.")

    # Validate params
    params = _validate_no_params()
    v = _check_supports_params(source, params)
    if v:
        latency = int((time.time() - t0) * 1000)
        _record_api_request(api_requests, None, source.get("id"), params, None, None, 400, latency, False)
        return v

    # Enforce rate limits/quotas
    rl = _enforce_rate_limit(api_requests, TOOL, None)
    if rl:
        latency = int((time.time() - t0) * 1000)
        _record_api_request(api_requests, None, source.get("id"), params, None, None, 429, latency, False)
        return rl

    # Cache key
    norm = _normalize_params(params)
    ck = _cache_key(TOOL, norm)

    # Prefer ready snapshot
    snap = _select_ready_snapshot(trend_snapshots, ck)
    served_from_cache = True
    used_snapshot = None

    if not snap:
        # No ready snapshot: if there's in-flight job, return stale if available; else upstream error.
        in_flight = None
        for j in fetch_jobs:
            if j.get("cache_key") == ck and j.get("status") in ("queued", "running"):
                in_flight = j
                break

        snap2 = _select_stale_snapshot(trend_snapshots, ck)
        if snap2 and in_flight:
            snap = snap2
            served_from_cache = True
        elif snap2:
            snap = snap2
            served_from_cache = True
        else:
            latency = int((time.time() - t0) * 1000)
            _record_api_request(api_requests, None, source.get("id"), norm, ck, None, 502, latency, False)
            return _err("UPSTREAM_ERROR", "No cached snapshot available and upstream fetch is not available.")

    used_snapshot = snap
    items = _assemble_items(used_snapshot.get("id"), snapshot_items, trend_items)

    latency = int((time.time() - t0) * 1000)
    _record_api_request(api_requests, None, source.get("id"), norm, ck, used_snapshot.get("id"), 200, latency, True)

    return {
        "tool_name": TOOL,
        "source": {"id": source.get("id"), "slug": source.get("slug"), "display_name": source.get("display_name")},
        "snapshot": {
            "id": used_snapshot.get("id"),
            "status": used_snapshot.get("status"),
            "generated_at": used_snapshot.get("generated_at"),
            "expires_at": used_snapshot.get("expires_at"),
            "cache_key": ck,
            "item_count": used_snapshot.get("item_count"),
        },
        "served_from_cache": True,
        "items": items,
        "meta": {"total": len(items), "has_more": False, "next_cursor": None},
    }

