        return "ck_" + hashlib.sha256(raw.encode("utf-8")).hexdigest()

    def _log_and_return(body, response_status, source_id=None, request_params=None, cache_key=None, snapshot_id=None, served_from_cache=False):
        latency_ms = int(max(0, (time.time() - t0) * 1000))
        req_row = {
            "id": _new_id("req"),
            "api_key_id": None,
            "tool_name": "get-zhihu-trending",
            "source_id": source_id,
            "request_params": request_params if isinstance(request_params, dict) else {},
            "cache_key": cache_key,
            "snapshot_id": snapshot_id,
            "response_status": int(response_status),
            "latency_ms": int(min(300000, latency_ms)),
            "served_from_cache": bool(served_from_cache),
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        api_requests.append(req_row)
        _save("api_requests.json", api_requests)
        return body

    # Basic rate limiting (observable dynamics) using api_requests log: 120 req/min per api_key_id(None bucket)
    window_s = 60
    limit_per_window = 120
    cutoff = now - datetime.timedelta(seconds=window_s)
    recent = 0
    for r in api_requests:
        if r.get("api_key_id") is None:
            dt = _parse_dt(r.get("created_at"))
            if dt and dt >= cutoff:
                recent += 1
    if recent >= limit_per_window:
        return _log_and_return(_err("RATE_LIMIT", "Too many requests in a short time."), 429, request_params={}, served_from_cache=False)

    # Validate params
    if limit is None:
        limit = 50
    if isinstance(limit, bool) or not isinstance(limit, (int, float)):
        return _log_and_return(_err("VALIDATION_ERROR", "limit must be a number."), 400, request_params={"limit": limit})
    if int(limit) != limit:
        # floats not allowed if not an integer value
        return _log_and_return(_err("VALIDATION_ERROR", "limit must be an integer value."), 400, request_params={"limit": limit})
    limit = int(limit)
    if limit <= 0 or limit > 100:
        return _log_and_return(_err("VALIDATION_ERROR", "limit must be between 1 and 100."), 400, request_params={"limit": limit})

    tool_name = "get-zhihu-trending"
    request_params = {"limit": limit}

    # Map tool_name -> source via sources.slug containing 'zhihu' or supports tool_name in supports_params meta
    # Prefer active sources first
    zhihu_candidates = []
    for s in sources:
        slug = s.get("slug")
        if slug == "zhihu" or slug == "zhihu-trending" or slug == "zhihu_hot" or (isinstance(slug, str) and "zhihu" in slug):
            zhihu_candidates.append(s)
    # fallback: any source whose supports_params declares limit range up to 100 and looks like trending
    if not zhihu_candidates:
        for s in sources:
            sp = s.get("supports_params")
            if isinstance(sp, dict) and "limit" in sp and (s.get("slug") or "").strip():
                if isinstance(s.get("slug"), str) and "zhihu" in s.get("slug"):
                    zhihu_candidates.append(s)

    source = None
    for s in zhihu_candidates:
        if s.get("status") == "active":
            source = s
            break
    if source is None and zhihu_candidates:
        # if all non-active, treat as not found for reads (source disabled)
        return _log_and_return(_err("NOT_FOUND", "Source is not available."), 404, source_id=zhihu_candidates[0].get("id"), request_params=request_params)

    if source is None:
        return _log_and_return(_err("NOT_FOUND", "Zhihu source is not configured."), 404, request_params=request_params)

    # Validate against supports_params (no undeclared fields, enum/range)
    supports = source.get("supports_params")
    if not isinstance(supports, dict):
        return _log_and_return(_err("VALIDATION_ERROR", "Source supports_params is invalid."), 400, source_id=source.get("id"), request_params=request_params)

    # Tool requires only 'limit'
    for k in request_params.keys():
        if k not in supports:
            return _log_and_return(_err("VALIDATION_ERROR", f"Parameter '{k}' is not supported by this source."), 400, source_id=source.get("id"), request_params=request_params)

    # Validate 'limit' with supports_params if present
    lim_rule = supports.get("limit")
    if isinstance(lim_rule, dict):
        rtype = lim_rule.get("type")
        if rtype == "range":
            mn = lim_rule.get("min")
            mx = lim_rule.get("max")
            if isinstance(mn, (int, float)) and limit < int(mn):
                return _log_and_return(_err("VALIDATION_ERROR", "limit is below minimum for this source."), 400, source_id=source.get("id"), request_params=request_params)
            if isinstance(mx, (int, float)) and limit > int(mx):
                return _log_and_return(_err("VALIDATION_ERROR", "limit exceeds maximum for this source."), 400, source_id=source.get("id"), request_params=request_params)

    ck = _cache_key(tool_name, {"limit": limit})

    # Find ready, unexpired snapshot by cache_key
    ready = []
    for snap in trend_snapshots:
        if snap.get("cache_key") == ck and snap.get("status") == "ready":
            exp = _parse_dt(snap.get("expires_at"))
            if exp and exp > now:
                ready.append(snap)

    def _dt_key(snap, field):
        dt = _parse_dt(snap.get(field))
        return dt or datetime.datetime.min

    if ready:
        ready.sort(key=lambda s: _dt_key(s, "generated_at"), reverse=True)
        snap = ready[0]
        sid = snap.get("id")
        # load snapshot_items rows ordered by rank, limit
        sis = [si for si in snapshot_items if si.get("snapshot_id") == sid]
        # Enforce consistency: item_count must equal rows count for zhihu tool rule
        if isinstance(snap.get("item_count"), int) and snap.get("item_count") != len(sis):
            # mark snapshot stale if inconsistent
            for ss in trend_snapshots:
                if ss.get("id") == sid and ss.get("status") == "ready":
                    ss["status"] = "stale"
                    ss["updated_at"] = now_iso
            _save("trend_snapshots.json", trend_snapshots)
            # fall through to try stale or not found
        else:
            sis.sort(key=lambda x: (x.get("rank") if isinstance(x.get("rank"), int) else 10**18))
            sis = sis[:limit]
            item_by_id = {it.get("id"): it for it in trend_items}
            items = []
            for si in sis:
                it = item_by_id.get(si.get("item_id"))
                if not it:
                    continue
                if it.get("status") != "active":
                    continue
                items.append({
                    "rank": si.get("rank"),
                    "score": si.get("score"),
                    "metrics": si.get("metrics") if isinstance(si.get("metrics"), dict) else {},
                    "extra": si.get("extra") if isinstance(si.get("extra"), dict) else {},
                    "item": it
                })
            body = {
                "data": {
                    "source": {"id": source.get("id"), "slug": source.get("slug"), "display_name": source.get("display_name")},
                    "snapshot": {"id": sid, "generated_at": snap.get("generated_at"), "expires_at": snap.get("expires_at"), "status": snap.get("status")},
                    "items": items
                },
                "meta": {"limit": limit, "returned": len(items), "served_from_cache": True}
            }
            return _log_and_return(body, 200, source_id=source.get("id"), request_params=request_params, cache_key=ck, snapshot_id=sid, served_from_cache=True)

    # If no ready snapshot, check for stale snapshot (best-effort), but if none ever fetched -> NOT_FOUND
    stale = []
    for snap in trend_snapshots:
        if snap.get("cache_key") == ck and snap.get("status") in ("stale", "ready"):
            stale.append(snap)
    if stale:
        stale.sort(key=lambda s: _dt_key(s, "generated_at"), reverse=True)
        snap = stale[0]
        sid = snap.get("id")
        sis = [si for si in snapshot_items if si.get("snapshot_id") == sid]
        sis.sort(key=lambda x: (x.get("rank") if isinstance(x.get("rank"), int) else 10**18))
        sis = sis[:limit]
        item_by_id = {it.get("id"): it for it in trend_items}
        items = []
        for si in sis:
            it = item_by_id.get(si.get("item_id"))
            if not it:
                continue
            if it.get("status") != "active":
                continue
            items.append({
                "rank": si.get("rank"),
                "score": si.get("score"),
                "metrics": si.get("metrics") if isinstance(si.get("metrics"), dict) else {},
                "extra": si.get("extra") if isinstance(si.get("extra"), dict) else {},
                "item": it
            })
        body = {
            "data": {
                "source": {"id": source.get("id"), "slug": source.get("slug"), "display_name": source.get("display_name")},
                "snapshot": {"id": sid, "generated_at": snap.get("generated_at"), "expires_at": snap.get("expires_at"), "status": snap.get("status")},
                "items": items
            },
            "meta": {"limit": limit, "returned": len(items), "served_from_cache": True, "note": "Returned latest available (may be stale)."}
        }
        return _log_and_return(body, 200, source_id=source.get("id"), request_params=request_params, cache_key=ck, snapshot_id=sid, served_from_cache=True)

    # If no snapshots exist, ensure we do not create a new running fetch_job on read; just NOT_FOUND
    return _log_and_return(_err("NOT_FOUND", "No available snapshots for this source yet."), 404, source_id=source.get("id"), request_params=request_params, cache_key=ck, served_from_cache=False)

def get_sources(status=None, slug=None, limit=None, cursor=None, order=None, **_extra):
    import json, os, datetime, time, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0382000" if __import__("os").path.isdir("./environment_mix/0382000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0)
    now_iso = now.isoformat() + "Z"

    api_requests = _load("api_requests.json")
    sources = _load("sources.json")

    def _new_id(prefix):
        return f"{prefix}_{datetime.datetime.utcnow().strftime('%Y%m%d%H%M%S')}_{hashlib.sha256(os.urandom(16)).hexdigest()[:16]}"

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str) or not s:
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1])
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _log_and_return(body, response_status, request_params=None):
        latency_ms = int(max(0, (time.time() - t0) * 1000))
        req_row = {
            "id": _new_id("req"),
            "api_key_id": None,
            "tool_name": "get-sources",
            "source_id": None,
            "request_params": request_params if isinstance(request_params, dict) else {},
            "cache_key": None,
            "snapshot_id": None,
            "response_status": int(response_status),
            "latency_ms": int(min(300000, latency_ms)),
            "served_from_cache": False,
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        api_requests.append(req_row)
        _save("api_requests.json", api_requests)
        return body

    # Rate limiting: 240 req/min
    window_s = 60
    limit_per_window = 240
    cutoff = now - datetime.timedelta(seconds=window_s)
    recent = 0
    for r in api_requests:
        if r.get("api_key_id") is None:
            dt = _parse_dt(r.get("created_at"))
            if dt and dt >= cutoff:
                recent += 1
    if recent >= limit_per_window:
        return _log_and_return(_err("RATE_LIMIT", "Too many requests in a short time."), 429, request_params={})

    # Validate
    req_params = {}
    if status is not None:
        if not isinstance(status, str):
            return _log_and_return(_err("VALIDATION_ERROR", "status must be a string."), 400, request_params={"status": status})
        if status not in ("active", "paused", "deprecated"):
            return _log_and_return(_err("VALIDATION_ERROR", "status must be one of: active, paused, deprecated."), 400, request_params={"status": status})
        req_params["status"] = status
    if slug is not None:
        if not isinstance(slug, str) or not slug.strip():
            return _log_and_return(_err("VALIDATION_ERROR", "slug must be a non-empty string."), 400, request_params={"slug": slug})
        req_params["slug"] = slug
    if limit is None:
        limit = 20
    if isinstance(limit, bool) or not isinstance(limit, int):
        return _log_and_return(_err("VALIDATION_ERROR", "limit must be an integer."), 400, request_params={"limit": limit, **req_params})
    if limit < 1 or limit > 100:
        return _log_and_return(_err("VALIDATION_ERROR", "limit must be between 1 and 100."), 400, request_params={"limit": limit, **req_params})
    req_params["limit"] = limit
    if cursor is not None:
        if not isinstance(cursor, str):
            return _log_and_return(_err("VALIDATION_ERROR", "cursor must be a string."), 400, request_params={"cursor": cursor, **req_params})
        req_params["cursor"] = cursor
    if order is None:
        order = "created_at_desc"
    if not isinstance(order, str):
        return _log_and_return(_err("VALIDATION_ERROR", "order must be a string."), 400, request_params={"order": order, **req_params})
    if order not in ("created_at_desc", "created_at_asc", "updated_at_desc", "updated_at_asc"):
        return _log_and_return(_err("VALIDATION_ERROR", "order is invalid."), 400, request_params={"order": order, **req_params})
    req_params["order"] = order

    rows = list(sources)

    if status is not None:
        rows = [r for r in rows if r.get("status") == status]
    if slug is not None:
        rows = [r for r in rows if r.get("slug") == slug]

    def _sort_key(r):
        dt = _parse_dt(r.get("created_at" if "created_at" in order else "updated_at"))
        return dt or datetime.datetime.min

    reverse = order.endswith("_desc")
    field = "created_at" if order.startswith("created_at") else "updated_at"
    rows.sort(key=lambda r: (_parse_dt(r.get(field)) or datetime.datetime.min, r.get("id") or ""), reverse=reverse)

    # Cursor is a simple opaque "idx:<n>"
    start_idx = 0
    if cursor:
        if cursor.startswith("idx:"):
            try:
                start_idx = int(cursor.split(":", 1)[1])
                if start_idx < 0:
                    start_idx = 0
            except Exception:
                return _log_and_return(_err("VALIDATION_ERROR", "cursor is invalid."), 400, request_params=req_params)
        else:
            return _log_and_return(_err("VALIDATION_ERROR", "cursor is invalid."), 400, request_params=req_params)

    page = rows[start_idx:start_idx + limit]
    next_idx = start_idx + len(page)
    has_more = next_idx < len(rows)
    next_cursor = f"idx:{next_idx}" if has_more else None

    body = {
        "data": page,
        "meta": {
            "total": len(rows),
            "limit": limit,
            "cursor": cursor,
            "has_more": has_more,
            "next_cursor": next_cursor,
            "order": order
        }
    }
    return _log_and_return(body, 200, request_params=req_params)

