    def _new_id(prefix):
        return f"{prefix}_{datetime.datetime.utcnow().strftime('%Y%m%d%H%M%S')}_{hashlib.sha256(os.urandom(16)).hexdigest()[:16]}"

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str) or not s:
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1])
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _log_and_return(body, response_status, source_id=None, request_params=None):
        latency_ms = int(max(0, (time.time() - t0) * 1000))
        req_row = {
            "id": _new_id("req"),
            "api_key_id": None,
            "tool_name": "update-source",
            "source_id": source_id,
            "request_params": request_params if isinstance(request_params, dict) else {},
            "cache_key": None,
            "snapshot_id": None,
            "response_status": int(response_status),
            "latency_ms": int(min(300000, latency_ms)),
            "served_from_cache": False,
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        api_requests.append(req_row)
        _save("api_requests.json", api_requests)
        return body

    # Rate limiting: 60 req/min for mutations
    window_s = 60
    limit_per_window = 60
    cutoff = now - datetime.timedelta(seconds=window_s)
    recent = 0
    for r in api_requests:
        if r.get("api_key_id") is None and r.get("tool_name") == "update-source":
            dt = _parse_dt(r.get("created_at"))
            if dt and dt >= cutoff:
                recent += 1
    if recent >= limit_per_window:
        return _log_and_return(_err("RATE_LIMIT", "Too many update requests in a short time."), 429, request_params={"id": id})

    if not isinstance(id, str) or not id.strip():
        return _log_and_return(_err("VALIDATION_ERROR", "id must be a non-empty string."), 400, request_params={"id": id})

    idx = None
    for i, s in enumerate(sources):
        if s.get("id") == id:
            idx = i
            break
    if idx is None:
        return _log_and_return(_err("NOT_FOUND", "Source not found."), 404, request_params={"id": id})

    row = sources[idx]
    req_params = {"id": id}
    if display_name is not None:
        req_params["display_name"] = display_name
        if not isinstance(display_name, str) or not display_name.strip():
            return _log_and_return(_err("VALIDATION_ERROR", "display_name must be a non-empty string."), 400, source_id=id, request_params=req_params)
    if default_language is not None:
        req_params["default_language"] = default_language
        if not isinstance(default_language, str):
            return _log_and_return(_err("VALIDATION_ERROR", "default_language must be a string."), 400, source_id=id, request_params=req_params)
        dl = default_language.strip()
        if len(dl) < 2 or len(dl) > 16:
            return _log_and_return(_err("VALIDATION_ERROR", "default_language length must be between 2 and 16."), 400, source_id=id, request_params=req_params)
        # basic BCP47-ish
        if not re.match(r"^[A-Za-z]{2,3}(-[A-Za-z0-9]{2,8})*$", dl):
