        if isinstance(cache_ttl_seconds, bool) or not isinstance(cache_ttl_seconds, int):
            return _log_and_return(_err("VALIDATION_ERROR", "cache_ttl_seconds must be an integer."), 400, source_id=id, request_params=req_params)
        if cache_ttl_seconds < 0 or cache_ttl_seconds > 2592000:
            return _log_and_return(_err("VALIDATION_ERROR", "cache_ttl_seconds must be between 0 and 2592000."), 400, source_id=id, request_params=req_params)
        # Enforce schema constraint for sources: 10..86400; allow 0 as per tool docs, else enforce range.
        if cache_ttl_seconds != 0 and (cache_ttl_seconds < 10 or cache_ttl_seconds > 86400):
            return _log_and_return(_err("VALIDATION_ERROR", "cache_ttl_seconds must be 0 or between 10 and 86400."), 400, source_id=id, request_params=req_params)
    if status is not None:
        req_params["status"] = status
        if not isinstance(status, str) or status not in ("active", "paused", "deprecated"):
            return _log_and_return(_err("VALIDATION_ERROR", "status must be one of: active, paused, deprecated."), 400, source_id=id, request_params=req_params)

    # Apply updates; enforce lifecycle transition
    changed = False

    if status is not None:
        cur = row.get("status")
        if cur != status:
            transitions = {
                "active": ["paused", "deprecated"],
                "paused": ["active", "deprecated"],
                "deprecated": []
            }
            allowed = transitions.get(cur, [])
            if status not in allowed:
                # tool text says VALIDATION_ERROR for illegal transition
                return _log_and_return(_err("INVALID_TRANSITION", f"Illegal status transition: {cur} -> {status}."), 409, source_id=id, request_params=req_params)
            row["status"] = status
            changed = True

    if display_name is not None and row.get("display_name") != display_name:
        row["display_name"] = display_name
        changed = True
    if default_language is not None and row.get("default_language") != default_language:
        row["default_language"] = default_language.strip()
        changed = True
    if base_url is not None and row.get("base_url") != base_url:
        row["base_url"] = base_url
        changed = True
    if cache_ttl_seconds is not None and row.get("cache_ttl_seconds") != cache_ttl_seconds:
        row["cache_ttl_seconds"] = cache_ttl_seconds
        changed = True

    if not changed:
        # No success without effect: if nothing to update, treat as conflict/no-op
        return _log_and_return(_err("CONFLICT", "No changes applied."), 409, source_id=id, request_params=req_params)

    row["updated_at"] = now_iso
    sources[idx] = row
    _save("sources.json", sources)

    body = {"data": row}
    return _log_and_return(body, 200, source_id=id, request_params=req_params)

def get_fetch_jobs(source_id=None, tool_name=None, cache_key=None, status=None, limit=None, cursor=None, order=None, **_extra):
    import json, os, datetime, time, uuid, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0382000" if __import__("os").path.isdir("./environment_mix/0382000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)
    now_iso = now.isoformat()

    # ---- validation ----
    if source_id is not None and (not isinstance(source_id, str) or len(source_id) < 1):
        return _err("VALIDATION_ERROR", "source_id must be a non-empty string")
    if tool_name is not None and (not isinstance(tool_name, str) or len(tool_name) < 1):
        return _err("VALIDATION_ERROR", "tool_name must be a non-empty string")
    if cache_key is not None and (not isinstance(cache_key, str) or len(cache_key) < 1):
        return _err("VALIDATION_ERROR", "cache_key must be a non-empty string")
    allowed_status = {"queued", "running", "succeeded", "failed", "cancelled"}
    if status is not None and (not isinstance(status, str) or status not in allowed_status):
        return _err("VALIDATION_ERROR", "status must be one of queued/running/succeeded/failed/cancelled")
    if limit is None:
        limit = 20
    if not isinstance(limit, int) or limit < 1 or limit > 100:
        return _err("VALIDATION_ERROR", "limit must be an integer in [1,100]")
    if cursor is not None and not isinstance(cursor, str):
        return _err("VALIDATION_ERROR", "cursor must be a string")
    if order is None:
        order = "created_at_desc"
    if not isinstance(order, str) or order not in {"created_at_desc", "created_at_asc"}:
        return _err("VALIDATION_ERROR", "order must be one of created_at_desc/created_at_asc")

    # ---- quota/rate limit (best-effort, based on api_requests history) ----
    # Policy: 120 requests/min, 5000 requests/day per api_key_id (or global if api_key_id is null)
    api_requests = _load("api_requests.json")
    api_key_id = None  # ambient auth: self-host may be null

    def _parse_dt(s):
        if not isinstance(s, str):
            return None
        try:
            dt = datetime.datetime.fromisoformat(s.replace("Z", "+00:00"))
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return None

    window_60s = now - datetime.timedelta(seconds=60)
    window_1d = now - datetime.timedelta(days=1)

    r60 = 0
    r1d = 0
    for r in api_requests:
        if not isinstance(r, dict):
            continue
        if r.get("api_key_id") != api_key_id:
            continue
        dt = _parse_dt(r.get("created_at"))
        if dt is None:
            continue
        if dt >= window_60s:
            r60 += 1
        if dt >= window_1d:
            r1d += 1

    if r60 >= 120:
        # log request before returning
        req_row = {
            "id": "req_" + uuid.uuid4().hex,
            "api_key_id": api_key_id,
            "tool_name": "get-fetch-jobs",
            "source_id": None,
            "request_params": {
                "source_id": source_id,
                "tool_name": tool_name,
                "cache_key": cache_key,
                "status": status,
                "limit": limit,
                "cursor": cursor,
                "order": order,
            },
            "cache_key": None,
            "snapshot_id": None,
            "response_status": 429,
            "latency_ms": int((time.time() - t0) * 1000),
            "served_from_cache": False,
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        api_requests.append(req_row)
        _save("api_requests.json", api_requests)
        return _err("RATE_LIMIT", "Rate limit exceeded")

    if r1d >= 5000:
        req_row = {
            "id": "req_" + uuid.uuid4().hex,
            "api_key_id": api_key_id,
            "tool_name": "get-fetch-jobs",
            "source_id": None,
            "request_params": {
                "source_id": source_id,
                "tool_name": tool_name,
                "cache_key": cache_key,
                "status": status,
                "limit": limit,
                "cursor": cursor,
                "order": order,
            },
            "cache_key": None,
            "snapshot_id": None,
            "response_status": 429,
            "latency_ms": int((time.time() - t0) * 1000),
            "served_from_cache": False,
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        api_requests.append(req_row)
        _save("api_requests.json", api_requests)
        return _err("QUOTA_EXCEEDED", "Daily quota exceeded")

    # ---- load data ----
    jobs = _load("fetch_jobs.json")

    # validate referenced source_id if provided (NOT_FOUND for missing reference)
    if source_id is not None:
        sources = _load("sources.json")
        if not any(isinstance(s, dict) and s.get("id") == source_id for s in sources):
            # log request before returning
            req_row = {
                "id": "req_" + uuid.uuid4().hex,
                "api_key_id": api_key_id,
                "tool_name": "get-fetch-jobs",
                "source_id": source_id,
                "request_params": {
                    "source_id": source_id,
                    "tool_name": tool_name,
                    "cache_key": cache_key,
                    "status": status,
                    "limit": limit,
                    "cursor": cursor,
                    "order": order,
                },
                "cache_key": None,
                "snapshot_id": None,
                "response_status": 404,
                "latency_ms": int((time.time() - t0) * 1000),
                "served_from_cache": False,
                "created_at": now_iso,
                "updated_at": now_iso,
            }
            api_requests.append(req_row)
            _save("api_requests.json", api_requests)
            return _err("NOT_FOUND", "source_id not found")

    # ---- filtering ----
    def _match(j):
        if not isinstance(j, dict):
            return False
        if source_id is not None and j.get("source_id") != source_id:
            return False
        if tool_name is not None and j.get("tool_name") != tool_name:
            return False
        if cache_key is not None and j.get("cache_key") != cache_key:
            return False
        if status is not None and j.get("status") != status:
            return False
        return True

    filtered = [j for j in jobs if _match(j)]

    # ---- sorting ----
    def _created_at_key(j):
        dt = _parse_dt(j.get("created_at"))
        if dt is None:
            return datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)
        return dt

    reverse = (order == "created_at_desc")
    filtered.sort(key=_created_at_key, reverse=reverse)

    # ---- cursor pagination ----
    # cursor encodes last_seen_created_at + last_seen_id to stabilize pagination
    start_index = 0
    if cursor:
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("utf-8") + b"===")
            payload = json.loads(raw.decode("utf-8"))
            last_created_at = payload.get("created_at")
            last_id = payload.get("id")
            last_dt = _parse_dt(last_created_at)
            if not isinstance(last_id, str) or last_dt is None:
                return _err("VALIDATION_ERROR", "Invalid cursor")
            # find first element strictly after the cursor position
            for i, j in enumerate(filtered):
                jdt = _created_at_key(j)
                jid = j.get("id")
                if not isinstance(jid, str):
                    continue
                if reverse:
                    # descending: we advance when (jdt, jid) < (last_dt, last_id)
                    if (jdt, jid) < (last_dt, last_id):
                        start_index = i
                        break
                    start_index = len(filtered)
                else:
                    # ascending: advance when (jdt, jid) > (last_dt, last_id)
                    if (jdt, jid) > (last_dt, last_id):
                        start_index = i
                        break
                    start_index = len(filtered)
        except Exception:
            return _err("VALIDATION_ERROR", "Invalid cursor")

    page = filtered[start_index:start_index + limit]
    has_more = (start_index + limit) < len(filtered)

    next_cursor = None
    if has_more and page:
        last = page[-1]
        payload = {"created_at": last.get("created_at"), "id": last.get("id")}
        next_cursor = base64.urlsafe_b64encode(json.dumps(payload, ensure_ascii=False).encode("utf-8")).decode("utf-8").rstrip("=")

    # ---- log request ----
    req_row = {
        "id": "req_" + uuid.uuid4().hex,
        "api_key_id": api_key_id,
        "tool_name": "get-fetch-jobs",
        "source_id": source_id,
        "request_params": {
            "source_id": source_id,
            "tool_name": tool_name,
            "cache_key": cache_key,
            "status": status,
            "limit": limit,
            "cursor": cursor,
            "order": order,
        },
        "cache_key": cache_key,
        "snapshot_id": None,
        "response_status": 200,
        "latency_ms": int((time.time() - t0) * 1000),
        "served_from_cache": False,
        "created_at": now_iso,
        "updated_at": now_iso,
    }
    api_requests.append(req_row)
    _save("api_requests.json", api_requests)

    return {
        "data": page,
        "meta": {
            "total": len(filtered),
            "limit": limit,
            "has_more": has_more,
            "next_cursor": next_cursor,
            "order": order,
        }
    }

def update_fetch_job(id, status, started_at=None, finished_at=None, http_status=None, error_code=None, error_message=None, items_fetched=None, snapshot=None, **_extra):
    import json, os, datetime, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0382000" if __import__("os").path.isdir("./environment_mix/0382000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)
    now_iso = now.isoformat()

    def _parse_dt(s, field_name):
        if s is None:
            return None, None
        if not isinstance(s, str) or not s:
            return None, _err("VALIDATION_ERROR", f"{field_name} must be an RFC3339 string")
        try:
            dt = datetime.datetime.fromisoformat(s.replace("Z", "+00:00"))
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc), None
        except Exception:
            return None, _err("VALIDATION_ERROR", f"{field_name} must be an RFC3339 string")

    # ---- validation ----
    if not isinstance(id, str) or len(id) < 1:
        return _err("VALIDATION_ERROR", "id must be a non-empty string")
    allowed_status = {"queued", "running", "succeeded", "failed", "cancelled"}
    if not isinstance(status, str) or status not in allowed_status:
        return _err("VALIDATION_ERROR", "status must be one of queued/running/succeeded/failed/cancelled")
    if http_status is not None and (not isinstance(http_status, int) or http_status < 100 or http_status > 599):
        return _err("VALIDATION_ERROR", "http_status must be an integer in [100,599]")
    if items_fetched is not None and (not isinstance(items_fetched, int) or items_fetched < 0):
        return _err("VALIDATION_ERROR", "items_fetched must be an integer >= 0")
    if error_code is not None and not isinstance(error_code, str):
        return _err("VALIDATION_ERROR", "error_code must be a string")
    if error_message is not None and not isinstance(error_message, str):
        return _err("VALIDATION_ERROR", "error_message must be a string")

    dt_started, e = _parse_dt(started_at, "started_at")
    if e:
        return e
    dt_finished, e = _parse_dt(finished_at, "finished_at")
    if e:
        return e

    # ---- log skeleton (will fill status/latency at end) ----
    api_requests = _load("api_requests.json")
    api_key_id = None  # ambient auth
    req_row = {
        "id": "req_" + uuid.uuid4().hex,
        "api_key_id": api_key_id,
        "tool_name": "update-fetch-job",
        "source_id": None,
        "request_params": {
            "id": id,
            "status": status,
            "started_at": started_at,
            "finished_at": finished_at,
            "http_status": http_status,
            "error_code": error_code,
            "error_message": error_message,
            "items_fetched": items_fetched,
            "snapshot": snapshot,
        },
        "cache_key": None,
        "snapshot_id": None,
        "response_status": 500,
        "latency_ms": 0,
        "served_from_cache": False,
        "created_at": now_iso,
        "updated_at": now_iso,
    }

    # ---- load fetch job ----
    jobs = _load("fetch_jobs.json")
    job_idx = None
    job = None
    for i, j in enumerate(jobs):
        if isinstance(j, dict) and j.get("id") == id:
            job_idx = i
            job = j
            break
    if job is None:
        req_row["response_status"] = 404
        req_row["latency_ms"] = int((time.time() - t0) * 1000)
        api_requests.append(req_row)
        _save("api_requests.json", api_requests)
        return _err("NOT_FOUND", "fetch_job not found")

    # ---- enforce state machine transitions ----
    transitions = {
        "queued": {"running", "cancelled"},
        "running": {"succeeded", "failed", "cancelled"},
        "succeeded": set(),
        "failed": set(),
        "cancelled": set(),
    }
    cur_status = job.get("status")
    if cur_status not in transitions:
        req_row["response_status"] = 409
        req_row["latency_ms"] = int((time.time() - t0) * 1000)
        api_requests.append(req_row)
        _save("api_requests.json", api_requests)
        return _err("CONFLICT", "fetch_job has invalid current status")
    if status != cur_status:
        if status not in transitions[cur_status]:
            req_row["response_status"] = 409
            req_row["latency_ms"] = int((time.time() - t0) * 1000)
            api_requests.append(req_row)
            _save("api_requests.json", api_requests)
            return _err("INVALID_TRANSITION", f"Cannot transition fetch_job from {cur_status} to {status}")

    # ---- if succeeded, validate and create snapshot + snapshot_items + upsert trend_items ----
    created_snapshot_id = None
    sources = _load("sources.json")
    trend_items = _load("trend_items.json")
    snapshots = _load("trend_snapshots.json")
    snapshot_items = _load("snapshot_items.json")

    def _src_exists(source_id):
        return any(isinstance(s, dict) and s.get("id") == source_id for s in sources)

    source_id = job.get("source_id")
    if not isinstance(source_id, str) or not source_id or not _src_exists(source_id):
        req_row["response_status"] = 404
        req_row["latency_ms"] = int((time.time() - t0) * 1000)
        api_requests.append(req_row)
        _save("api_requests.json", api_requests)
        return _err("NOT_FOUND", "source_id referenced by fetch_job not found")

    tool_name = job.get("tool_name")
    cache_key = job.get("cache_key")
    if status == "succeeded":
        if not isinstance(snapshot, dict):
            req_row["response_status"] = 400
            req_row["latency_ms"] = int((time.time() - t0) * 1000)
            api_requests.append(req_row)
            _save("api_requests.json", api_requests)
            return _err("VALIDATION_ERROR", "snapshot is required when status=succeeded")

        # required fields
        for k in ("generated_at", "expires_at", "item_count", "items"):
            if k not in snapshot:
                req_row["response_status"] = 400
                req_row["latency_ms"] = int((time.time() - t0) * 1000)
                api_requests.append(req_row)
                _save("api_requests.json", api_requests)
                return _err("VALIDATION_ERROR", f"snapshot.{k} is required")

        gen_dt, e = _parse_dt(snapshot.get("generated_at"), "snapshot.generated_at")
        if e:
            req_row["response_status"] = 400
            req_row["latency_ms"] = int((time.time() - t0) * 1000)
            api_requests.append(req_row)
            _save("api_requests.json", api_requests)
            return e
        exp_dt, e = _parse_dt(snapshot.get("expires_at"), "snapshot.expires_at")
        if e:
            req_row["response_status"] = 400
            req_row["latency_ms"] = int((time.time() - t0) * 1000)
            api_requests.append(req_row)
            _save("api_requests.json", api_requests)
            return e
        if exp_dt <= gen_dt:
            req_row["response_status"] = 400
            req_row["latency_ms"] = int((time.time() - t0) * 1000)
            api_requests.append(req_row)
            _save("api_requests.json", api_requests)
            return _err("VALIDATION_ERROR", "snapshot.expires_at must be > snapshot.generated_at")

        item_count = snapshot.get("item_count")
        if not isinstance(item_count, int) or item_count < 0:
            req_row["response_status"] = 400
            req_row["latency_ms"] = int((time.time() - t0) * 1000)
            api_requests.append(req_row)
            _save("api_requests.json", api_requests)
            return _err("VALIDATION_ERROR", "snapshot.item_count must be an integer >= 0")

        items = snapshot.get("items")
        if not isinstance(items, list):
            req_row["response_status"] = 400
            req_row["latency_ms"] = int((time.time() - t0) * 1000)
            api_requests.append(req_row)
            _save("api_requests.json", api_requests)
            return _err("VALIDATION_ERROR", "snapshot.items must be an array")

        if len(items) != item_count:
            req_row["response_status"] = 400
            req_row["latency_ms"] = int((time.time() - t0) * 1000)
            api_requests.append(req_row)
            _save("api_requests.json", api_requests)
            return _err("VALIDATION_ERROR", "snapshot.item_count must match number of snapshot.items")

        # validate ranks uniqueness and start from 1
        ranks = []
        for it in items:
            if not isinstance(it, dict):
                req_row["response_status"] = 400
                req_row["latency_ms"] = int((time.time() - t0) * 1000)
                api_requests.append(req_row)
                _save("api_requests.json", api_requests)
                return _err("VALIDATION_ERROR", "Each snapshot.items element must be an object")
            if "rank" not in it or "item" not in it:
                req_row["response_status"] = 400
                req_row["latency_ms"] = int((time.time() - t0) * 1000)
                api_requests.append(req_row)
                _save("api_requests.json", api_requests)
                return _err("VALIDATION_ERROR", "Each snapshot.items element requires rank and item")
            r = it.get("rank")
            if not isinstance(r, int) or r < 1:
                req_row["response_status"] = 400
                req_row["latency_ms"] = int((time.time() - t0) * 1000)
                api_requests.append(req_row)
                _save("api_requests.json", api_requests)
                return _err("VALIDATION_ERROR", "snapshot.items[].rank must be an integer >= 1")
            ranks.append(r)
        if len(set(ranks)) != len(ranks):
            req_row["response_status"] = 409
            req_row["latency_ms"] = int((time.time() - t0) * 1000)
            api_requests.append(req_row)
            _save("api_requests.json", api_requests)
            return _err("CONFLICT", "Duplicate rank within snapshot.items")
        if item_count > 0 and min(ranks) != 1:
            req_row["response_status"] = 400
            req_row["latency_ms"] = int((time.time() - t0) * 1000)
            api_requests.append(req_row)
            _save("api_requests.json", api_requests)
            return _err("VALIDATION_ERROR", "Ranks must start from 1")
        if item_count > 0 and max(ranks) != item_count:
            # enforce contiguous ranks to simplify paging
            req_row["response_status"] = 400
            req_row["latency_ms"] = int((time.time() - t0) * 1000)
            api_requests.append(req_row)
            _save("api_requests.json", api_requests)
            return _err("VALIDATION_ERROR", "Ranks must be contiguous from 1..item_count")

        # idempotency: if already succeeded and snapshot exists for same job_id with status=ready, return it
        if cur_status == "succeeded":
            existing = None
            for s in snapshots:
                if isinstance(s, dict) and s.get("fetch_job_id") == id and s.get("status") == "ready":
                    existing = s
                    break
            if existing:
                # Still update mutable fields on job (timestamps/http_status/items_fetched) if provided
                if dt_started is not None:
                    job["started_at"] = dt_started.isoformat()
                if dt_finished is not None:
                    job["finished_at"] = dt_finished.isoformat()
                if http_status is not None:
                    job["http_status"] = http_status
                if items_fetched is not None:
                    job["items_fetched"] = items_fetched
                job["updated_at"] = now_iso
                jobs[job_idx] = job
                _save("fetch_jobs.json", jobs)

                req_row["source_id"] = source_id
                req_row["cache_key"] = cache_key
                req_row["snapshot_id"] = existing.get("id")
                req_row["response_status"] = 200
                req_row["latency_ms"] = int((time.time() - t0) * 1000)
                api_requests.append(req_row)
                _save("api_requests.json", api_requests)
                return {"data": {"fetch_job": job, "snapshot": existing}}

        # create new snapshot row (unique(cache_key, generated_at))
        for s in snapshots:
            if isinstance(s, dict) and s.get("cache_key") == cache_key and s.get("generated_at") == gen_dt.isoformat():
                req_row["response_status"] = 409
                req_row["latency_ms"] = int((time.time() - t0) * 1000)
                api_requests.append(req_row)
                _save("api_requests.json", api_requests)
                return _err("CONFLICT", "A snapshot with the same cache_key and generated_at already exists")

        snapshot_id = "snap_" + uuid.uuid4().hex
        snap_row = {
            "id": snapshot_id,
            "source_id": source_id,
            "fetch_job_id": id,
            "tool_name": tool_name,
            "request_params": job.get("request_params") if isinstance(job.get("request_params"), dict) else {},
            "cache_key": cache_key,
            "status": "ready",
            "generated_at": gen_dt.isoformat(),
            "expires_at": exp_dt.isoformat(),
            "item_count": item_count,
            "created_at": now_iso,
            "updated_at": now_iso,
        }

        # upsert trend_items and build snapshot_items rows
        # constraints:
        # - trend_items unique(source_id, canonical_key)
        # - title <> ''
        # - url is null or startswith http
        # - content_type enum in trend_items schema (includes many); tool snapshot allows subset and 'rank'
        # We'll map 'rank' -> 'unknown' to fit trend_items enum.
        allowed_item_status = {"active", "removed", "blocked"}
        item_transitions = {
            "active": {"removed", "blocked"},
            "removed": {"active", "blocked"},
            "blocked": set(),
        }
        allowed_content_type_snapshot = {"news", "post", "video", "rank"}
        allowed_content_type_store = {"news", "article", "video", "topic", "book", "product", "post", "unknown"}

        def _find_item_by_key(source_id, canonical_key):
            for idx, ti in enumerate(trend_items):
                if isinstance(ti, dict) and ti.get("source_id") == source_id and ti.get("canonical_key") == canonical_key:
                    return idx, ti
            return None, None

        # Ensure no duplicate item in same snapshot (by canonical_key, effectively item_id)
        seen_item_ids = set()

        new_snapshot_items = []
        for it in items:
            item_obj = it.get("item")
            if not isinstance(item_obj, dict):
                req_row["response_status"] = 400
                req_row["latency_ms"] = int((time.time() - t0) * 1000)
                api_requests.append(req_row)
                _save("api_requests.json", api_requests)
                return _err("VALIDATION_ERROR", "snapshot.items[].item must be an object")

            # required fields
            for rk in ("canonical_key", "url", "title"):
                if rk not in item_obj:
                    req_row["response_status"] = 400
                    req_row["latency_ms"] = int((time.time() - t0) * 1000)
                    api_requests.append(req_row)
                    _save("api_requests.json", api_requests)
                    return _err("VALIDATION_ERROR", f"snapshot.items[].item.{rk} is required")

            canonical_key = item_obj.get("canonical_key")
            url = item_obj.get("url")
            title = item_obj.get("title")

            if not isinstance(canonical_key, str) or not canonical_key:
                req_row["response_status"] = 400
                req_row["latency_ms"] = int((time.time() - t0) * 1000)
                api_requests.append(req_row)
                _save("api_requests.json", api_requests)
                return _err("VALIDATION_ERROR", "canonical_key must be a non-empty string")
            if not isinstance(url, str) or not url or not url.startswith("http"):
                req_row["response_status"] = 400
                req_row["latency_ms"] = int((time.time() - t0) * 1000)
                api_requests.append(req_row)
                _save("api_requests.json", api_requests)
                return _err("VALIDATION_ERROR", "url must be a non-empty string starting with 'http'")
            if not isinstance(title, str) or not title.strip():
                req_row["response_status"] = 400
                req_row["latency_ms"] = int((time.time() - t0) * 1000)
                api_requests.append(req_row)
                _save("api_requests.json", api_requests)
                return _err("VALIDATION_ERROR", "title must be a non-empty string")

            lang = item_obj.get("language")
            if lang is not None:
                if not isinstance(lang, str) or len(lang) < 2 or len(lang) > 16:
                    req_row["response_status"] = 400
                    req_row["latency_ms"] = int((time.time() - t0) * 1000)
                    api_requests.append(req_row)
                    _save("api_requests.json", api_requests)
                    return _err("VALIDATION_ERROR", "language must be a string with length 2..16")

            pub_dt, e = _parse_dt(item_obj.get("published_at"), "snapshot.items[].item.published_at")
            if e:
                req_row["response_status"] = 400
                req_row["latency_ms"] = int((time.time() - t0) * 1000)
                api_requests.append(req_row)
                _save("api_requests.json", api_requests)
                return e

            ctype = item_obj.get("content_type")
            if ctype is None:
                ctype = "unknown"
            if not isinstance(ctype, str) or ctype not in allowed_content_type_snapshot:
                req_row["response_status"] = 400
                req_row["latency_ms"] = int((time.time() - t0) * 1000)
                api_requests.append(req_row)
                _save("api_requests.json", api_requests)
                return _err("VALIDATION_ERROR", "content_type must be one of news/post/video/rank")

            store_ctype = "unknown" if ctype == "rank" else ctype
            if store_ctype not in allowed_content_type_store:
                store_ctype = "unknown"

            raw_payload = item_obj.get("raw_payload")
            if raw_payload is None:
                raw_payload = {}
            if not isinstance(raw_payload, dict):
                req_row["response_status"] = 400
                req_row["latency_ms"] = int((time.time() - t0) * 1000)
                api_requests.append(req_row)
                _save("api_requests.json", api_requests)
                return _err("VALIDATION_ERROR", "raw_payload must be an object")

            new_item_status = item_obj.get("status")
            if new_item_status is None:
                new_item_status = "active"
            if not isinstance(new_item_status, str) or new_item_status not in allowed_item_status:
                req_row["response_status"] = 400
                req_row["latency_ms"] = int((time.time() - t0) * 1000)
                api_requests.append(req_row)
                _save("api_requests.json", api_requests)
                return _err("VALIDATION_ERROR", "item.status must be one of active/removed/blocked")

            idx, existing = _find_item_by_key(source_id, canonical_key)
            if existing is None:
                # create
                item_id = "ti_" + uuid.uuid4().hex
                ti_row = {
                    "id": item_id,
                    "source_id": source_id,
                    "canonical_key": canonical_key,
                    "source_content_id": item_obj.get("source_content_id"),
                    "url": url,
                    "title": title,
                    "summary": item_obj.get("summary"),
                    "author": item_obj.get("author"),
                    "language": lang,
                    "published_at": pub_dt.isoformat() if pub_dt is not None else None,
                    "content_type": store_ctype,
                    "raw_payload": raw_payload,
                    "status": new_item_status,
                    "created_at": now_iso,
                    "updated_at": now_iso,
                }
                trend_items.append(ti_row)
            else:
                # update fields; enforce status transition if changed
                item_id = existing.get("id")
                cur_item_status = existing.get("status")
                if cur_item_status in item_transitions and new_item_status != cur_item_status:
                    if new_item_status not in item_transitions[cur_item_status]:
                        req_row["response_status"] = 409
                        req_row["latency_ms"] = int((time.time() - t0) * 1000)
                        api_requests.append(req_row)
                        _save("api_requests.json", api_requests)
                        return _err("INVALID_TRANSITION", f"Cannot transition trend_item from {cur_item_status} to {new_item_status}")
                # apply updates
                existing["source_content_id"] = item_obj.get("source_content_id")
                existing["url"] = url
                existing["title"] = title
                existing["summary"] = item_obj.get("summary")
                existing["author"] = item_obj.get("author")
                existing["language"] = lang
                existing["published_at"] = pub_dt.isoformat() if pub_dt is not None else None
                existing["content_type"] = store_ctype
                existing["raw_payload"] = raw_payload
                existing["status"] = new_item_status
                existing["updated_at"] = now_iso
                trend_items[idx] = existing

            if not isinstance(item_id, str) or not item_id:
                req_row["response_status"] = 500
                req_row["latency_ms"] = int((time.time() - t0) * 1000)
                api_requests.append(req_row)
                _save("api_requests.json", api_requests)
                return _err("CONFLICT", "Failed to resolve item id")

            # enforce unique(snapshot_id, item_id) within new snapshot
            if item_id in seen_item_ids:
                req_row["response_status"] = 409
                req_row["latency_ms"] = int((time.time() - t0) * 1000)
                api_requests.append(req_row)
                _save("api_requests.json", api_requests)
                return _err("CONFLICT", "Duplicate item in snapshot.items (same canonical_key resolved to same item_id)")
            seen_item_ids.add(item_id)

            sc = it.get("score")
            if sc is not None and (not isinstance(sc, (int, float)) or sc < 0):
                req_row["response_status"] = 400
                req_row["latency_ms"] = int((time.time() - t0) * 1000)
                api_requests.append(req_row)
                _save("api_requests.json", api_requests)
                return _err("VALIDATION_ERROR", "score must be a number >= 0 or null")

            metrics = it.get("metrics")
            if metrics is None:
                metrics = {}
            if not isinstance(metrics, dict):
                req_row["response_status"] = 400
                req_row["latency_ms"] = int((time.time() - t0) * 1000)
                api_requests.append(req_row)
                _save("api_requests.json", api_requests)
                return _err("VALIDATION_ERROR", "metrics must be an object")

            extra = it.get("extra")
            if extra is None:
                extra = {}
            if not isinstance(extra, dict):
                req_row["response_status"] = 400
                req_row["latency_ms"] = int((time.time() - t0) * 1000)
                api_requests.append(req_row)
                _save("api_requests.json", api_requests)
                return _err("VALIDATION_ERROR", "extra must be an object")

            # unique(snapshot_id, rank) in-store must also hold; since new snapshot_id is unique, only within list matters
            si_row = {
                "id": "si_" + uuid.uuid4().hex,
                "snapshot_id": snapshot_id,
                "item_id": item_id,
                "rank": it.get("rank"),
                "score": float(sc) if isinstance(sc, (int, float)) else None,
                "metrics": metrics,
                "extra": extra,
                "created_at": now_iso,
                "updated_at": now_iso,
            }
            new_snapshot_items.append(si_row)

        # Persist snapshot and items and trend_items
        snapshots.append(snap_row)
        snapshot_items.extend(new_snapshot_items)

        # Update job required fields for succeeded
        job["status"] = "succeeded"
        if dt_started is not None:
            job["started_at"] = dt_started.isoformat()
        if dt_finished is not None:
            job["finished_at"] = dt_finished.isoformat()
        if job.get("finished_at") is None:
            # set finished_at to generated_at if not provided
            job["finished_at"] = gen_dt.isoformat()
        if job.get("started_at") is None:
            job["started_at"] = gen_dt.isoformat()
        if http_status is not None:
            job["http_status"] = http_status
        if items_fetched is not None:
            job["items_fetched"] = items_fetched
        else:
            job["items_fetched"] = item_count
        job["error_code"] = None
        job["error_message"] = None
        job["updated_at"] = now_iso
        jobs[job_idx] = job

        _save("trend_items.json", trend_items)
        _save("trend_snapshots.json", snapshots)
        _save("snapshot_items.json", snapshot_items)
        _save("fetch_jobs.json", jobs)

        created_snapshot_id = snapshot_id

    else:
        # not succeeded: snapshot must not create ready snapshot
        if snapshot is not None:
            req_row["response_status"] = 400
            req_row["latency_ms"] = int((time.time() - t0) * 1000)
            api_requests.append(req_row)
            _save("api_requests.json", api_requests)
            return _err("VALIDATION_ERROR", "snapshot must be omitted unless status=succeeded")

        # apply state update and fields
        # idempotent when status == cur_status: still allow updating timestamps/http/error/items_fetched
        if status != cur_status:
            job["status"] = status

        if dt_started is not None:
            job["started_at"] = dt_started.isoformat()
        if dt_finished is not None:
            job["finished_at"] = dt_finished.isoformat()
        if http_status is not None:
            job["http_status"] = http_status

        if status in {"failed", "cancelled"}:
            job["error_code"] = error_code
            # truncate error_message to 2000 chars
            if error_message is not None and len(error_message) > 2000:
                job["error_message"] = error_message[:2000]
            else:
                job["error_message"] = error_message
        else:
            # queued/running: clear error fields if explicitly provided? keep existing unless provided
            if error_code is not None:
                job["error_code"] = error_code
            if error_message is not None:
                job["error_message"] = error_message[:2000] if len(error_message) > 2000 else error_message

        if items_fetched is not None:
            job["items_fetched"] = items_fetched

        # auto timestamps: entering running sets started_at if missing; entering terminal sets finished_at if missing
        if status == "running" and job.get("started_at") is None:
            job["started_at"] = now_iso
        if status in {"failed", "cancelled"} and job.get("finished_at") is None:
            job["finished_at"] = now_iso

        job["updated_at"] = now_iso
        jobs[job_idx] = job
        _save("fetch_jobs.json", jobs)

    # ---- write api_requests log ----
    req_row["source_id"] = source_id
    req_row["cache_key"] = cache_key
    req_row["snapshot_id"] = created_snapshot_id
    req_row["response_status"] = 200
    req_row["latency_ms"] = int((time.time() - t0) * 1000)
    req_row["updated_at"] = now_iso
    api_requests.append(req_row)
    _save("api_requests.json", api_requests)

    # return updated job + snapshot if created
    out = {"fetch_job": job}
    if created_snapshot_id is not None:
        # return the snapshot row we just created
        snap = None
        for s in snapshots:
            if isinstance(s, dict) and s.get("id") == created_snapshot_id:
                snap = s
                break
        out["snapshot"] = snap
    return {"data": out}
